$(function(){if($('a[href*="#"]:not([href="#"])').click(function(){if(!$(this).parent().hasClass("carousel")&&!$(this).parent().parent().hasClass("carousel")&&!$(this).hasClass("nav-link")&&location.pathname.replace(/^\//,"")===this.pathname.replace(/^\//,"")&&location.hostname===this.hostname){var t=$(this.hash);if((t=t.length?t:$("[name="+this.hash.slice(1)+"]")).length)return $("html, body").animate({scrollTop:t.offset().top-80},1e3),!1}}),$(location.href.split("#")[1])){var t=$("#"+location.href.split("#")[1]);if(t.length)return $("html,body").animate({scrollTop:t.offset().top-80},100),!1}});